INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Office-Paket immer für Textverarbeitung geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Textverarbeitung ist eine Kernfunktion"}, {"text": "Nein", "correct": false, "because": "Alle Pakete bieten diese Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion eines Office-Pakets ist für die Erstellung von Präsentationen entscheidend?', 3, '[{"text": "Präsentationssoftware", "correct": true, "because": "Ermöglicht Folien und Animationen"}, {"text": "Tabellenkalkulation", "correct": false, "because": "Dient der Datenanalyse"}, {"text": "Datenbankverwaltung", "correct": false, "because": "Für Datenspeicherung gedacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Office-Pakete enthalten immer eine Tabellenkalkulation. b) Sie sind nur für große Unternehmen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tabellenkalkulation ist Standard"}, {"text": "Beides stimmt", "correct": false, "because": "Auch für Privatnutzer geeignet"}, {"text": "Nur b) stimmt", "correct": false, "because": "Tabellenkalkulation ist üblich"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal eines Office-Pakets ist für die Zusammenarbeit im Team wichtig?', 4, '[{"text": "Cloud-Integration", "correct": true, "because": "Ermöglicht Echtzeit-Zusammenarbeit"}, {"text": "Anzahl der Schriftarten", "correct": false, "because": "Kein Einfluss auf Kollaboration"}, {"text": "Installationsgröße", "correct": false, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Office-Paket ohne Internetverbindung effektiv genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Lokale Funktionen bleiben verfügbar"}, {"text": "Nein", "correct": false, "because": "Internet ist nicht zwingend nötig"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Office-Paket immer für die Erstellung von Tabellen geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Tabellenkalkulation ist Standardbestandteil"}, {"text": "Nein", "correct": false, "because": "Fast alle Pakete bieten diese Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente eines Office-Pakets ist für die Datenanalyse entscheidend?', 3, '[{"text": "Tabellenkalkulation", "correct": true, "because": "Ermöglicht Berechnungen und Diagramme"}, {"text": "Textverarbeitung", "correct": false, "because": "Für Dokumente gedacht"}, {"text": "E-Mail-Client", "correct": false, "because": "Für Kommunikation genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Office-Pakete unterstützen immer Cloud-Speicherung. b) Sie sind für den privaten Gebrauch ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Cloud hängt vom Anbieter ab"}, {"text": "Beides stimmt", "correct": false, "because": "Privatnutzung ist möglich"}, {"text": "Nur b) stimmt", "correct": false, "because": "Office-Pakete sind vielseitig"}, {"text": "Beides falsch", "correct": true, "because": "Beides ist nicht zwingend wahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal eines Office-Pakets solltest du für die Zusammenarbeit im Team priorisieren?', 4, '[{"text": "Echtzeit-Kollaboration", "correct": true, "because": "Ermöglicht gleichzeitige Bearbeitung"}, {"text": "Anzahl der Vorlagen", "correct": false, "because": "Weniger entscheidend"}, {"text": "Installationszeit", "correct": false, "because": "Kein Einfluss auf Teamarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Office-Paket ohne Lizenz legal genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Lizenz ist rechtlich erforderlich"}, {"text": "Ja", "correct": false, "because": "Ohne Lizenz ist es illegal"}]');
